package ch.bbw.zork;/** * Group: Cat team, * Version: 1.0, * Date: October 2026  */import java.io.BufferedReader;import java.io.IOException;import java.io.InputStream;import java.io.InputStreamReader;import java.io.PrintStream;/** * Reads a line from the input and turns it into a {@link Command}. * Upper and lower case is ignored. If the input ends (end of file), * the parser returns the command "quit". */public class Parser {	private final CommandWords validCommandWords;	private final BufferedReader bufferedReader;	private final PrintStream out;	/**	 * Creates a parser which prints the prompt to System.out.	 *	 * @param inputStream where the commands are read from	 */	public Parser(InputStream inputStream) {		this(inputStream, System.out);	}	/**	 * Creates a parser.	 *	 * @param inputStream where the commands are read from	 * @param out         where the prompt is printed	 */	public Parser(InputStream inputStream, PrintStream out) {		this.bufferedReader = new BufferedReader(new InputStreamReader(inputStream));		this.validCommandWords = new CommandWords();		this.out = out;	}	/**	 * Reads the next line and creates a command. Everything after the first word	 * is the second word (so that names with a space also work).	 *	 * @return the command, never null. Its command word is null if it is unknown	 */	public Command getCommand() {		out.print("> ");		try {			String inputLine = bufferedReader.readLine();			if (inputLine == null) {				return new Command("quit");			}			return parse(inputLine);		} catch (IOException exc) {			out.println("There was an error during reading: " + exc.getMessage());		}		return new Command(null);	}	/**	 * Turns one line of text into a command.	 *	 * @param inputLine the text typed by the player	 * @return the command	 */	Command parse(String inputLine) {		String[] tokens = inputLine.trim().split("\\s+", 2);		String word1 = tokens[0].toLowerCase();		String word2 = tokens.length > 1 ? tokens[1] : null;		if (validCommandWords.isCommand(word1)) {			return new Command(word1, word2);		}		return new Command(null, word2);	}	/** @return all valid command words as text */	public String showCommands() {		return validCommandWords.showAll();	}}